ns.Locale("frFR", function(L)
	L["crest.alterac.description"] = "Une tour brisée sur un pic glacé. Le royaume a disparu. Les ruisseaux sont toujours bons."
	L["crest.alterac.name"] = "La tour brisée"
	L["crest.arathi.description"] = "De vieilles pierres levées dans l’herbe des hautes terres, plus vieilles que tous ceux qui se disputent à leur sujet."
	L["crest.arathi.name"] = "Les pierres levées"
	L["crest.ashenvale.description"] = "Un feu follet qui dérive entre les arbres sombres. La forêt remarque chaque pêcheur qui s’attarde trop."
	L["crest.ashenvale.name"] = "Le feu follet"
	L["crest.azshara.description"] = "Une colonne d’un ancien empire, que la mer escalade. Quelque chose nage encore dans ces ruines."
	L["crest.azshara.name"] = "La colonne tombée"
	L["crest.badlands.description"] = "Une arche de pierre que le vent a mis dix mille ans à achever. Apportez votre propre eau."
	L["crest.badlands.name"] = "L’arche de pierre"
	L["crest.barrens.description"] = "Un arbre au sommet plat dans les plaines arides. Chaque oasis, là-bas, est le coin préféré de quelqu’un."
	L["crest.barrens.name"] = "L’acacia"
	L["crest.blackrock.description"] = "Une montagne noire, du feu dans ses failles et des chaînes en travers de sa porte. Pêchez dans les bassins de lave à vos risques et périls."
	L["crest.blackrock.name"] = "La flèche noire"
	L["crest.blastedlands.description"] = "Une porte de pierre noire avec un feu vert à l’intérieur. Personne n’y pêche pour la vue."
	L["crest.blastedlands.name"] = "La porte ardente"
	L["crest.burningsteppes.description"] = "Une montagne en feu sous un ciel de cendre. L’eau y est assez chaude pour cuisiner."
	L["crest.burningsteppes.name"] = "Le pic ardent"
	L["crest.darkshore.description"] = "Un croissant de lune au-dessus de l’eau grise, pour les pêcheurs qui pêchent la nuit."
	L["crest.darkshore.name"] = "Le croissant"
	L["crest.darnassus.description"] = "Un puits à la lueur argentée sous un grand arbre. Le lac qui l’entoure abrite les poissons de la cité."
	L["crest.darnassus.name"] = "Le puits d’argent"
	L["crest.deadwind.description"] = "Une haute tour dans une vallée morte. Les bassins sont calmes. Trop calmes, disent certains, avant de repartir."
	L["crest.deadwind.name"] = "La tour solitaire"
	L["crest.desolace.description"] = "Un grand crâne cornu venu d’un vieux cimetière. La côte est plus clémente que l’intérieur des terres."
	L["crest.desolace.name"] = "Le crâne cornu"
	L["crest.dunmorogh.description"] = "Des cornes enroulées au-dessus d’un champ de neige. Les béliers de là-haut ont leur avis sur les étrangers."
	L["crest.dunmorogh.name"] = "Le bélier"
	L["crest.durotar.description"] = "Un scorpide sur la terre rouge. La côte est de meilleure compagnie que les scorpides."
	L["crest.durotar.name"] = "Le scorpide"
	L["crest.duskwood.description"] = "Deux yeux entre les arbres noirs. Là-bas, les pêcheurs gardent la lanterne allumée et la ligne courte."
	L["crest.duskwood.name"] = "Des yeux dans les bois"
	L["crest.dustwallow.description"] = "Une lanterne restée allumée sur la cabane d’un pêcheur, dans la brume du marais."
	L["crest.dustwallow.name"] = "La lanterne"
	L["crest.easternplague.description"] = "Une petite chapelle qui garde sa lumière face à la flétrissure. De la bonne eau coule à côté."
	L["crest.easternplague.name"] = "La chapelle"
	L["crest.elwynn.description"] = "Le premier lac que la plupart des pêcheurs aient jamais vu, et le chêne sous lequel ils se sont assis."
	L["crest.elwynn.name"] = "Le vieux chêne"
	L["crest.felwood.description"] = "Un arbre tordu, le feu vert dans les veines. Lavez chaque prise venue de là-bas. Deux fois."
	L["crest.felwood.name"] = "L’arbre souillé"
	L["crest.feralas.description"] = "De l’eau qui tombe entre les arbres géants, pour les pêcheurs qui prennent le chemin le plus long."
	L["crest.feralas.name"] = "Les chutes"
	L["crest.hillsbrad.description"] = "Trois pommes des vergers des contreforts. Les truites sous le moulin s’engraissent des fruits tombés."
	L["crest.hillsbrad.name"] = "Trois pommes"
	L["crest.hinterlands.description"] = "De grandes plumes des collines sauvages, où de grands oiseaux nichent au-dessus des rivières."
	L["crest.hinterlands.name"] = "Trois plumes"
	L["crest.hyjal.description"] = "Une pousse verte qui sort de vieilles braises. La montagne guérit, et ses ruisseaux avec elle."
	L["crest.hyjal.name"] = "La pousse"
	L["crest.hyjalcrater.description"] = "Une eau dormante dans un anneau brisé de pierre noire. Quelque chose a brûlé ici, autrefois ; le lac n’en a rien dit."
	L["crest.hyjalcrater.name"] = "Le lac du cratère"
	L["crest.ironforge.description"] = "Une enclume devant la forge de la montagne. Il y a un lac là-dessous, et des nains y pêchent."
	L["crest.ironforge.name"] = "L’enclume"
	L["crest.lochmodan.description"] = "Un barrage qui retient un lac des hautes terres. Les nains l’ont bâti pour durer, et il a duré."
	L["crest.lochmodan.name"] = "Le grand barrage"
	L["crest.lordamere.description"] = "Une île boisée sur un vaste lac gris, une barque tirée sur sa rive. De l’eau calme, et en quantité."
	L["crest.lordamere.name"] = "L’île du lac"
	L["crest.moonglade.description"] = "Des bois de cerf au-dessus d’un lac immobile, sous la lune. Un endroit calme, tenu calme exprès."
	L["crest.moonglade.name"] = "Les bois de cerf"
	L["crest.mulgore.description"] = "Un totem sculpté dans les longues plaines herbeuses, où les ruisseaux descendent clairs des collines."
	L["crest.mulgore.name"] = "Le totem"
	L["crest.orgrimmar.description"] = "Une porte hérissée de pointes dans un canyon rouge. Les bassins de la cité sont plus profonds qu’il n’y paraît."
	L["crest.orgrimmar.name"] = "La porte hérissée"
	L["crest.redridge.description"] = "Trois pics rouges dressés dans un lac de montagne, et chacun s’y reflète."
	L["crest.redridge.name"] = "Trois pics"
	L["crest.riverglades.description"] = "Une péniche sur une rivière sinueuse entre des collines vertes. Le commerce arrive par l’eau, et les poissons aussi."
	L["crest.riverglades.name"] = "La péniche"
	L["crest.searinggorge.description"] = "Un creuset qui déverse de l’or en fusion. Pêcher là-bas, c’est pêcher dans la lave : prévoyez de la patience et une longue canne."
	L["crest.searinggorge.name"] = "Le creuset"
	L["crest.shendralas.description"] = "Un livre ouvert sur un piédestal brisé, gardé par des gens qui n’ont jamais cessé de lire."
	L["crest.shendralas.name"] = "Le tome ouvert"
	L["crest.silithus.description"] = "Un scarabée sur le sable du désert. Les lacs y sont petits et suspects."
	L["crest.silithus.name"] = "Le scarabée"
	L["crest.silverpine.description"] = "Des pins argentés sur la rive d’un lac sombre. Quelque chose hurle là-bas presque toutes les nuits."
	L["crest.silverpine.name"] = "Pins argentés"
	L["crest.stonetalon.description"] = "Une grande serre agrippée à une pierre. De l’eau de montagne, froide et vive."
	L["crest.stonetalon.name"] = "La serre"
	L["crest.stormwind.description"] = "Des murs blancs et une porte au-dessus des canaux. La cité pêche dans ses propres voies d’eau, poliment."
	L["crest.stormwind.name"] = "Le donjon blanc"
	L["crest.stranglethorn.description"] = "Un poisson qui jaillit au-dessus des vagues de la jungle, comme s’il avait entendu parler du concours."
	L["crest.stranglethorn.name"] = "Le bond"
	L["crest.swampofsorrows.description"] = "Un toit de temple qui perce l’eau du marais. Ce qui est dessous reste dessous."
	L["crest.swampofsorrows.name"] = "Le sanctuaire noyé"
	L["crest.tanaris.description"] = "Un soleil de désert au-dessus de la seule ombre à des lieues à la ronde : le rivage."
	L["crest.tanaris.name"] = "Le soleil du désert"
	L["crest.teldrassil.description"] = "Un arbre si haut que sa cime touche les étoiles. Ses racines boivent une eau très ancienne."
	L["crest.teldrassil.name"] = "La couronne étoilée"
	L["crest.thousandneedles.description"] = "Des aiguilles de pierre qui jaillissent de la plaine. Pêchez dans leur ombre, et gardez votre chapeau."
	L["crest.thousandneedles.name"] = "Les aiguilles"
	L["crest.thunderbluff.description"] = "Une haute mesa avec une tente au sommet. Les bassins en contrebas recueillent les chutes, et les poissons avec."
	L["crest.thunderbluff.name"] = "La mesa"
	L["crest.tirisfal.description"] = "Une chauve-souris devant une lune maladive. Même les poissons ont l’air un peu fatigués, là-bas."
	L["crest.tirisfal.name"] = "La chauve-souris"
	L["crest.undercity.description"] = "Une couronne brisée au-dessus de canaux verts. La cour a disparu. Les canaux, eux, ont encore des poissons."
	L["crest.undercity.name"] = "La couronne brisée"
	L["crest.ungoro.description"] = "Une empreinte de la taille d’une barque. Le cratère a de plus grands soucis que les poissons."
	L["crest.ungoro.name"] = "L’empreinte"
	L["crest.veiledsea.description"] = "Un navire à demi perdu dans un banc de brume marine. Ici, les poissons remontent de très profond, et tout le reste aussi."
	L["crest.veiledsea.name"] = "Le banc de brume"
	L["crest.westernplague.description"] = "Un corbeau sur un arbre mort, au-dessus des champs vides. Les fermiers sont partis. Pas les poissons."
	L["crest.westernplague.name"] = "Le corbeau"
	L["crest.westfall.description"] = "Des ailes qui tournent au-dessus de la route côtière. La mer est plus proche que les fermiers ne l’admettent."
	L["crest.westfall.name"] = "Le moulin"
	L["crest.wetlands.description"] = "L’ancre d’un port, remontée de la vase. Elle en garde encore une légère odeur."
	L["crest.wetlands.name"] = "L’ancre"
	L["crest.winterspring.description"] = "Un flocon de neige au-dessus d’une eau immobile, là où la pêche sous la glace est de la vraie pêche."
	L["crest.winterspring.name"] = "Le givre"
	L["crest.zephras.description"] = "Une île qui flotte sur les nuages, son navire amarré à la pierre. L’eau est très loin en dessous."
	L["crest.zephras.name"] = "L’île flottante"
	L["family.1.name"] = "Lutjan"
	L["family.2.name"] = "Poisson-chat"
	L["family.3.name"] = "Mérou"
	L["family.4.name"] = "Rouget"
	L["family.5.name"] = "Saumon"
	L["family.6.name"] = "Homard"
	L["family.7.name"] = "Barracuda"
	L["ledgergood.ledger.binding.abyssal.description"] = "Noir comme l’eau profonde, avec une pâle lueur qui ondule sous la surface. Pour les pêcheurs qui sont allés au fond dix fois, et en sont revenus."
	L["ledgergood.ledger.binding.abyssal.name"] = "Noir abyssal"
	L["ledgergood.ledger.binding.carapace.description"] = "La carapace d’un crabe qui se croyait plus gros que le bateau, et qui l’était presque. Elle pince encore les pages pour les tenir fermées."
	L["ledgergood.ledger.binding.carapace.name"] = "Carapace de crabe"
	L["ledgergood.ledger.binding.ember.description"] = "Des écailles de quelque chose qui a vécu trop près de la forge, encore chaudes au cœur. Ne la laissez pas sur la table de chevet."
	L["ledgergood.ledger.binding.ember.name"] = "Écaille de braise"
	L["ledgergood.ledger.binding.flywallet.description"] = "De la toile cirée avec une laine sur le devant, et dans la laine, les mouches qui ont marché. Celles qui n’ont pas marché sont au fond du lac."
	L["ledgergood.ledger.binding.flywallet.name"] = "Portefeuille à mouches"
	L["ledgergood.ledger.binding.heartwood.description"] = "Deux planches de vieux chêne, un poisson profondément sculpté sur le devant, et un lierre que personne n’a planté là et qu’on ne convaincra pas de partir."
	L["ledgergood.ledger.binding.heartwood.name"] = "Cœur de chêne sculpté"
	L["ledgergood.ledger.binding.iridescent.description"] = "Des écailles de toutes les couleurs que l’eau a jamais livrées, posées l’une sur l’autre. Elle n’a jamais deux fois le même aspect."
	L["ledgergood.ledger.binding.iridescent.name"] = "Écaille irisée"
	L["ledgergood.ledger.binding.keeper.description"] = "Un vélin crème presque enseveli sous l’or. Réservé au pêcheur dont le livre n’a plus rien à trouver."
	L["ledgergood.ledger.binding.keeper.name"] = "L’or du gardien"
	L["ledgergood.ledger.binding.knit.description"] = "Une couverture tricotée dans la même laine que le pull du pêcheur, brandebourgs compris. Elle sent un peu la pluie et tient plus chaud qu’elle n’en a le droit."
	L["ledgergood.ledger.binding.knit.name"] = "Tricot torsadé"
	L["ledgergood.ledger.binding.lacquer.description"] = "Trente couches de laque noire, deux koï posées à l’or, et un dos cousu de soie rouge. Il faut un an pour la faire et une seconde pour y laisser une empreinte."
	L["ledgergood.ledger.binding.lacquer.name"] = "Koï sur laque noire"
	L["ledgergood.ledger.binding.legend.description"] = "Du cuir bleu gaufré d’écailles, et sur le plat trois poissons dorés qui se poursuivent dans le même cercle."
	L["ledgergood.ledger.binding.legend.name"] = "Trois poissons dorés"
	L["ledgergood.ledger.binding.level10.description"] = "Une peau plus claire et plus souple, polie aux coins par quelques saisons de pouces mouillés."
	L["ledgergood.ledger.binding.level10.name"] = "Peau tannée"
	L["ledgergood.ledger.binding.level20.description"] = "Un cuir bleu profond aux filets d’argent, couleur de port au crépuscule."
	L["ledgergood.ledger.binding.level20.name"] = "Bleu des marées"
	L["ledgergood.ledger.binding.level30.description"] = "Un cuir vert sombre, doré couleur de roseau sec, avec une légère odeur de berge."
	L["ledgergood.ledger.binding.level30.name"] = "Vert roseau"
	L["ledgergood.ledger.binding.level40.description"] = "Un cuir rouge profond et une dorure lourde. Le sang de poisson s’y voit à peine."
	L["ledgergood.ledger.binding.level40.name"] = "Sang-de-bœuf"
	L["ledgergood.ledger.binding.level50.description"] = "Un cuir gris ardoise aux fers d’argent, pour les jours où personne d’autre ne sort."
	L["ledgergood.ledger.binding.level50.name"] = "Gris d’orage"
	L["ledgergood.ledger.binding.level60.description"] = "Un cuir presque noir et un or éclatant. À peu près ce qui se fait de mieux pour le livre d’un pêcheur."
	L["ledgergood.ledger.binding.level60.name"] = "La reliure de Nat"
	L["ledgergood.ledger.binding.logbook.description"] = "Des plats de toile et des coins en veau, une boussole incrustée dans la couverture et une sangle contre les embruns. La tache d’eau était offerte."
	L["ledgergood.ledger.binding.logbook.name"] = "Journal de capitaine"
	L["ledgergood.ledger.binding.monster.description"] = "Une peau écailleuse de quelque chose qui ne voulait pas être pris, fermée par l’une de ses propres dents."
	L["ledgergood.ledger.binding.monster.name"] = "Peau de monstre"
	L["ledgergood.ledger.binding.stormglass.description"] = "Des plats de fer, des pentures et une fenêtre avec une tempête enfermée dedans. Personne ne se souvient d’y avoir mis le poisson."
	L["ledgergood.ledger.binding.stormglass.name"] = "Reliquaire de verre-tempête"
	L["ledgergood.ledger.binding.wave.description"] = "Du maroquin bleu frappé d’une seule grande vague, sa crête rehaussée d’or. Quelque part sur son épaule, un tout petit bateau."
	L["ledgergood.ledger.binding.wave.name"] = "La vague"
	L["ledgergood.ledger.soundset.choir.description"] = "Des voix graves qui montent des eaux profondes, et quelque chose de très grand qui chante avec elles, en dessous."
	L["ledgergood.ledger.soundset.choir.name"] = "Chœur des profondeurs"
	L["ledgergood.ledger.soundset.concertina.description"] = "Une phrase de concertina tirée d’un chant de marin que tout le monde connaît à moitié, jouée par quelqu’un qui le connaît en entier."
	L["ledgergood.ledger.soundset.concertina.name"] = "Concertina du vieux loup de mer"
	L["ledgergood.ledger.toaststyle.blueprint.description"] = "Tracé à l’atelier entre trois autres inventions et un petit feu. Échelle un pour un, tolérances facultatives, prise garantie (non garantie)."
	L["ledgergood.ledger.toaststyle.blueprint.name"] = "Plan du bricoleur"
	L["ledgergood.ledger.toaststyle.cartographer.description"] = "Une carte qui n’est jamais finie. Chaque eau que vous connaissez par cœur y est encrée : côte, collines, sondes au large. Le reste demeure au crayon, en attente."
	L["ledgergood.ledger.toaststyle.cartographer.name"] = "Portfolio du cartographe"
	L["ledgergood.ledger.toaststyle.crier.description"] = "Lue sur la place à midi, entre le prix du pain et le chevalier qu’on vient d’adouber. Chaque mot en est vrai, à un pouce près."
	L["ledgergood.ledger.toaststyle.crier.name"] = "Proclamation du crieur public"
	L["ledgergood.ledger.toaststyle.deep.description"] = "Écrit à la seule lumière du fond du lac. Quelque chose, là-dessous, tient la prise entre ses dents et n’est pas pressé de la lâcher."
	L["ledgergood.ledger.toaststyle.deep.name"] = "Le leurre des profondeurs"
	L["ledgergood.ledger.toaststyle.drum.description"] = "Tendu sur un cadre près du feu, peint de la main du clan et frappé assez fort pour réveiller la vallée voisine. Un coup pour chaque poisson qui mérite d’être raconté."
	L["ledgergood.ledger.toaststyle.drum.name"] = "Tambour de clan"
	L["ledgergood.ledger.toaststyle.gala.description"] = "Le soir du grand concours, quand tout le port suspend ses lumières et que personne ne rentre avant le feu d’artifice. Celui-ci est pour les pêcheurs qui ont rapporté les trois."
	L["ledgergood.ledger.toaststyle.gala.name"] = "Gala du concours"
	L["ledgergood.ledger.toaststyle.glade.description"] = "Écrit au clair de lune au bord d’un bassin sacré, où l’eau se souvient de tout ce qui y a jamais nagé. Les feux follets sont venus lire par-dessus votre épaule."
	L["ledgergood.ledger.toaststyle.glade.name"] = "Clairière étoilée"
	L["ledgergood.ledger.toaststyle.glass.description"] = "Une fenêtre d’une chapelle au bord de l’eau, sertie de plomb à la main. Les mots tiennent dans le seul carreau clair ; le reste est rubis, cobalt et couleur de lumière tardive."
	L["ledgergood.ledger.toaststyle.glass.name"] = "Vitrail de chapelle"
	L["ledgergood.ledger.toaststyle.hall.description"] = "Taillé dans la roche vive sous la montagne et incrusté par un forgeron qui a mesuré deux fois et s’en est vanté trois. Les runes gardent la forge au chaud."
	L["ledgergood.ledger.toaststyle.hall.name"] = "Salle de la montagne"
	L["ledgergood.ledger.toaststyle.hex.description"] = "Assemblé par un sorcier-docteur sur une île où les poissons mordent en retour. Le masque a vu votre avenir : encore des poissons. Le masque a vu pire."
	L["ledgergood.ledger.toaststyle.hex.name"] = "Maléfice de la jungle"
	L["ledgergood.ledger.toaststyle.ice.description"] = "Un demi-pied de bonne glace noire, un trou et beaucoup d’attente. Quand le fanion se lève, vous courez, et le froid ne vous gêne plus."
	L["ledgergood.ledger.toaststyle.ice.name"] = "À travers la glace"
	L["ledgergood.ledger.toaststyle.koi.description"] = "Un rouleau d’un peintre qui n’a jamais peint que des poissons, et les a bien peints. Le cercle autour de la prise a tenu en un souffle."
	L["ledgergood.ledger.toaststyle.koi.name"] = "Encre et koï"
	L["ledgergood.ledger.toaststyle.legend.description"] = "Réservé aux prises dont on discute sur les quais pendant des années. Bordure dorée, soie bleue, un vrai sceau."
	L["ledgergood.ledger.toaststyle.legend.name"] = "L’histoire à dormir debout"
	L["ledgergood.ledger.toaststyle.lion.description"] = "Taillée dans la pierre blanche d’une cité portuaire qui ne cesse jamais de bâtir, et scellée sous le lion de ses rois. Les bannières ne flottent que pour une prise digne des trompettes."
	L["ledgergood.ledger.toaststyle.lion.name"] = "Charte du lion"
	L["ledgergood.ledger.toaststyle.prestige.description"] = "Un vélin sang-de-bœuf et des lauriers dorés, pour un pêcheur qui a tout recommencé et l’a refait en entier."
	L["ledgergood.ledger.toaststyle.prestige.name"] = "Vélin sang-de-bœuf"
	L["ledgergood.ledger.toaststyle.shroud.description"] = "Arraché au drap dans lequel on vous a enterré, et recousu quand vous en êtes sorti pour aller pêcher. La prise s’en moque. La prise n’en sait rien."
	L["ledgergood.ledger.toaststyle.shroud.name"] = "Linceul"
	L["ledgergood.ledger.toaststyle.slate.description"] = "Écrite à la craie ce matin, sur la glace à midi. Le prix, c’est ce que le poissonnier pense que vous pouvez supporter."
	L["ledgergood.ledger.toaststyle.slate.name"] = "Ardoise du poissonnier"
	L["ledgergood.ledger.toaststyle.stitch.description"] = "Brodé par quelqu’un de patient pendant les longues nuits entre les saisons. Chaque poisson a pris une soirée ; l’aiguille y est encore."
	L["ledgergood.ledger.toaststyle.stitch.name"] = "Abécédaire au point de croix"
	L["ledgergood.ledger.toaststyle.totem.description"] = "Peint sur une peau près d’un feu, sous un très grand ciel, par quelqu’un qui croit que chaque poisson est un don de la Terre. Dites merci."
	L["ledgergood.ledger.toaststyle.totem.name"] = "Totem des plaines"
	L["ledgergood.ledger.toaststyle.trophy.description"] = "Noyer, laiton et quatre bonnes vis. Le genre de chose qu’on accroche au-dessus de la cheminée et qu’on montre du doigt le reste de la soirée."
	L["ledgergood.ledger.toaststyle.trophy.name"] = "Trophée monté"
	L["ledgergood.ledger.toaststyle.warband.description"] = "Martelé sous un ciel rouge, dans une cité bâtie de fer et de rancunes. Les braseros brûlent pour le clan ; les marques de griffes sont pour quiconque a douté de la prise."
	L["ledgergood.ledger.toaststyle.warband.name"] = "Bande de guerre de fer"
	L["legend.19803.blurb"] = "La plupart des pêcheurs n’en voient jamais que le sillage. Celui-ci a ralenti assez longtemps pour être pris."
	L["legend.19803.title"] = "Chasseur de tassergal"
	L["legend.19805.blurb"] = "Bien trop beau pour une table de concours, et il semble le savoir."
	L["legend.19805.title"] = "Rival de Keefer"
	L["legend.19806.blurb"] = "Porte beau comme un prince, et se bat comme s’il avait une couronne à perdre."
	L["legend.19806.title"] = "Attrape-reine"
	L["line.uncaughtjunk.text"] = "Le socle est épousseté et prêt. La pièce exposée est en retard."
	L["line.uncaughtlegend.text"] = "Certains poissons ne se prennent qu’une fois de loin en loin. Cette page en attend un."
	L["line.uncaughttreasure.text"] = "Quelque chose de scellé, pas encore trouvé."
	L["line.unchartedwaters.text"] = "Eaux inexplorées. Aucune carte de celles-ci pour l’instant."
	L["prestigeframe.castoff.description"] = "Le plat-bord d’une barque à clins, épais de trois couches de peinture, les avirons rentrés en travers."
	L["prestigeframe.castoff.name"] = "Larguer les amarres"
	L["prestigeframe.constellation.description"] = "Passé le dixième, on vous met dans le ciel : un pêcheur d’étoiles avec une canne et une ligne, et un poisson au bout. Une étoile de plus à la couronne pour chaque Prestige de maître."
	L["prestigeframe.constellation.name"] = "La constellation du pêcheur"
	L["prestigeframe.coral.description"] = "Un anneau de nacre dans un récif : du corail rouge d’un côté, une gorgone de l’autre, et toujours quelqu’un qui passe à la nage."
	L["prestigeframe.coral.name"] = "Les jardins de corail"
	L["prestigeframe.dive.description"] = "Un casque de scaphandrier en cuivre, boulonné et gonflé d’air. Le pêcheur est passé par-dessus bord pour regarder le poisson dans les yeux."
	L["prestigeframe.dive.name"] = "La plongée"
	L["prestigeframe.jetty.description"] = "Des planches de la vieille jetée, liées en anneau, qui sentent encore le goudron et la marée basse."
	L["prestigeframe.jetty.name"] = "La jetée"
	L["prestigeframe.leviathan.description"] = "Le serpent au fond de toutes les histoires de marin, enroulé autour d’un anneau de vieil or, la queue dans la gueule."
	L["prestigeframe.leviathan.name"] = "Le léviathan"
	L["prestigeframe.lighthouse.description"] = "La salle de la lanterne au bout de la pointe, vitrée tout autour, la lumière filant sur l’eau."
	L["prestigeframe.lighthouse.name"] = "Le phare"
	L["prestigeframe.midnight.description"] = "Du verre noir venu de là où aucune lumière ne descend, éclairé par ce qui vit là-bas. L’un d’eux s’intéresse à vous."
	L["prestigeframe.midnight.name"] = "La zone de minuit"
	L["prestigeframe.none.description"] = "Un anneau à l’encre, et une supposition au crayon de ce qui viendra autour."
	L["prestigeframe.none.name"] = "Non écrit"
	L["prestigeframe.opensea.description"] = "Une rose des vents tirée d’une carte de navigateur, chaque pointe juste, le nord couronné d’or."
	L["prestigeframe.opensea.name"] = "La haute mer"
	L["prestigeframe.starward.description"] = "Là où finit la mer commence le ciel : une sphère armillaire d’or et d’argent sous la nuit, et les vieux poissons parmi les étoiles."
	L["prestigeframe.starward.name"] = "La mer vers les étoiles"
	L["prestigeframe.storm.description"] = "La barre d’un ketch en plein coup de vent : acajou, laiton et huit bons rayons, et le ciel qui se déchire au-dessus."
	L["prestigeframe.storm.name"] = "La tempête"
	L["species.12238.blurb"] = "Large, lent et gris comme la côte dont il porte le nom. Il fait un meilleur ragoût qu’une première impression."
	L["species.12238.riddle"] = "Eau grise sous de vieux arbres sur une côte au clair de lune, ou loin au sud, dans le désert."
	L["species.13422.blurb"] = "Les armuriers paient bien les écailles. L’anguille n’est pas d’accord avec l’arrangement."
	L["species.13422.riddle"] = "Un essaim qui se tord en eau de mer profonde, au large des côtes les plus sauvages."
	L["species.13754.blurb"] = "Assez lourd pour que certains pêcheurs le pêchent assis."
	L["species.13754.riddle"] = "Haute mer au large des côtes lointaines, assez profonde pour les lourds."
	L["species.13755.blurb"] = "Arrive avec le givre. Plus de bras qu’un pêcheur ne peut raisonnablement en démêler."
	L["species.13755.riddle"] = "Rivages chauds, une fois que l’année tourne au froid."
	L["species.13756.blurb"] = "Arrive avec les longues journées et repart au premier vent froid."
	L["species.13756.riddle"] = "Rivages chauds, pendant la moitié chaude de l’année."
	L["species.13757.blurb"] = "Ça picote. Ne la léchez pas."
	L["species.13757.riddle"] = "Un crépitement dans des eaux lointaines et sauvages, du lever du soleil jusque tard le soir."
	L["species.13758.blurb"] = "Des ouïes comme des braises. Mord comme s’il le pensait vraiment."
	L["species.13758.riddle"] = "Eaux intérieures des terres les plus sauvages, de jour comme de nuit."
	L["species.13759.blurb"] = "Se nourrit à la lumière des étoiles. Les pêcheurs qui le veulent apprennent à aimer le noir."
	L["species.13759.riddle"] = "Eaux sauvages loin des rivages paisibles, après le coucher du soleil."
	L["species.13760.blurb"] = "Se lève avec le soleil et veille tard. Personne ne sait où il va avant l’aube."
	L["species.13760.riddle"] = "Rivières et lacs lointains, chauds ou froids, tant que le soleil est levé."
	L["species.13888.blurb"] = "Pince d’abord, et ne pose jamais de questions."
	L["species.13888.riddle"] = "Eaux rocheuses et profondes, aux confins du monde."
	L["species.13889.blurb"] = "Pâle comme le givre. Meilleur mangé le jour même, ce qui est rarement possible."
	L["species.13889.riddle"] = "Les eaux les plus lointaines qui soient, des lacs gelés aux collines brûlées."
	L["species.13890.blurb"] = "Porte son armure à l’extérieur et son caractère à l’intérieur. Prévoyez un couteau plus lourd."
	L["species.13890.riddle"] = "Quelque chose de lourd dans les eaux les plus lointaines, après le coucher du soleil."
	L["species.13893.blurb"] = "Le grand cousin. Il vous faudra les deux mains, et sans doute un ami."
	L["species.13893.riddle"] = "Eau profonde au large d’une côte lointaine et oubliée."
	L["species.1467.blurb"] = "Un petit poisson joyeux qui n’a aucune idée du nombre de cuisiniers qui l’attendent."
	L["species.1467.riddle"] = "Un calme lac de colline, en pays de fermes paisibles."
	L["species.16967.blurb"] = "Gros, rapide et bon à manger. La plupart sont pêchés pour rendre service à quelqu’un d’autre, ce qui semble du gâchis."
	L["species.16967.riddle"] = "Un large fleuve à travers une forêt humide et envahie, dans le lointain ouest."
	L["species.16968.blurb"] = "Frappe l’appât comme s’il attendait une dispute depuis le matin."
	L["species.16968.riddle"] = "Un rivage morne et gris, sur une côte occidentale sèche et vide."
	L["species.16969.blurb"] = "Cette voile, c’est pour la frime, et il le sait. Se bat comme s’il avait un public."
	L["species.16969.riddle"] = "Hauts-fonds chauds de la jungle, où la mer monte jusqu’aux arbres."
	L["species.16970.blurb"] = "Vif comme un oiseau de la jungle, et deux fois plus pénible au bout de la ligne."
	L["species.16970.riddle"] = "Hauts-fonds chauds et troubles, là où un marais rejoint la mer."
	L["species.19807.blurb"] = "Poisson de concours. A le goût de la victoire, ou au moins d’un long après-midi à essayer."
	L["species.19807.riddle"] = "Seulement pendant le grand concours de la jungle."
	L["species.19975.blurb"] = "Sent exactement ce que son nom promet. Quelqu’un, quelque part, en veut encore une douzaine."
	L["species.19975.riddle"] = "Eau brune et agitée, au cœur de la jungle fumante."
	L["species.21071.blurb"] = "Sent les collines le long desquelles il nage."
	L["species.21071.riddle"] = "Petits bancs dans les collines et les forêts, au léger parfum d’herbes."
	L["species.21153.blurb"] = "La petite a grandi."
	L["species.21153.riddle"] = "Des bancs plus grands au parfum d’herbes, dans les collines enneigées et la jungle fumante."
	L["species.251524.blurb"] = "Nouveau dans ces eaux, et personne ne sait trop comment il est arrivé là."
	L["species.251524.riddle"] = "De nouveaux bancs éclatants sur un lac tranquille des collines de l’est."
	L["species.4603.blurb"] = "Rapide, brillant, et très content de lui."
	L["species.4603.riddle"] = "Côtes salées au nord et au sud, des deux côtés de la mer."
	L["species.6289.blurb"] = "Il mord à tout, y compris, une fois, à la botte d’un gnome."
	L["species.6289.riddle"] = "Rivières paresseuses des terres où les héros commencent."
	L["species.6291.blurb"] = "Petit, brillant et partout. Le livre de tout pêcheur commence ici, et personne n’avoue combien il en a relâché."
	L["species.6291.riddle"] = "La toute première chose à tirer sur la ligne d’un débutant, dans les eaux les plus douces qui soient."
	L["species.6299.blurb"] = "Mauvaise mine, pire odeur, et une fois cuit, quelque chose qu’un raptor mangerait."
	L["species.6299.riddle"] = "Eau grise et lasse dans le nord lugubre, des deux côtés de la mer."
	L["species.6303.blurb"] = "Glissant comme personne. Frit bien mieux qu’il n’en a le droit."
	L["species.6303.riddle"] = "Côtes peu profondes, où pataugent les nouveaux aventuriers."
	L["species.6308.blurb"] = "Tout en moustaches et en rancune. Il boude au fond jusqu’à ce qu’il décide de se battre."
	L["species.6308.riddle"] = "Rivières troubles, des deux côtés de la mer."
	L["species.6317.blurb"] = "Nommé par des nains, qui nomment tout d’après la façon dont ça se comporte quand on essaie de le tenir."
	L["species.6317.riddle"] = "Eau froide d’un lac des hautes terres, en pays nain."
	L["species.6358.blurb"] = "Les alchimistes en veulent l’huile. Les cuisiniers n’en veulent rien du tout."
	L["species.6358.riddle"] = "Un banc qui laisse une nappe sur les eaux côtières."
	L["species.6359.blurb"] = "Tiède au toucher, même hors de l’eau."
	L["species.6359.riddle"] = "Des bancs tourbillonnants couleur de braise, au large des côtes du nord et du sud."
	L["species.6361.blurb"] = "Les couleurs s’effacent dans l’heure qui suit la prise. Regardez vite."
	L["species.6361.riddle"] = "Côte ouverte, un peu plus loin du rivage que d’habitude."
	L["species.6362.blurb"] = "Têtue au bout de la ligne, douce dans l’assiette."
	L["species.6362.riddle"] = "Côtes marines, du nord brumeux au sud brûlant, là où le fond plonge."
	L["species.6458.blurb"] = "Moins un poisson qu’un avertissement sur l’eau. Lavez-le deux fois, puis réfléchissez encore."
	L["species.6458.riddle"] = "Eau souillée, là où les gobelins forent les collines et les plaines desséchées."
	L["species.6522.blurb"] = "À manger à vos risques et périls. Pas deux pêcheurs qui en ont mangé ne racontent la même histoire de l’heure qui a suivi."
	L["species.6522.riddle"] = "D’étranges bancs dans les plaines arides, là où l’eau elle-même semble malade."
	L["species.8365.blurb"] = "La tête brille vraiment. Non, ce n’est pas du mithril. Arrêtez de demander au forgeron."
	L["species.8365.riddle"] = "Lacs et rivières en pays plus rude, de la forêt profonde au désert nu."
	L["sub.13874.plaque"] = "Trop lourde pour flotter et trop lourde pour être portée loin. Quelqu’un a essayé les deux."
	L["sub.13875.plaque"] = "Cerclé de fer et verrouillé en plus. Ce qu’il y a dedans valait l’inquiétude."
	L["sub.13881.plaque"] = "Trop gourmand pour arrêter de manger, et trop plein pour s’enfuir à la nage."
	L["sub.13918.plaque"] = "Renforcé, verrouillé, et coulé quand même. Certaines cargaisons n’ont jamais de chance."
	L["sub.20708.plaque"] = "Scellée si bien que l’eau n’y est jamais entrée. Le propriétaire non plus, semble-t-il."
	L["sub.21113.plaque"] = "Étanche, comme promis. Personne n’avait promis qu’elle flotterait."
	L["sub.21150.plaque"] = "Le fer a tenu. Le navire d’où elle vient, non."
	L["sub.21162.plaque"] = "Enflé, visqueux et plein de la chance de quelqu’un d’autre. Lavez-vous les mains après."
	L["sub.21164.plaque"] = "Têtue jusqu’au bout. Elle n’a rendu ce qu’elle avait avalé qu’au couteau."
	L["sub.21228.plaque"] = "Cerclée de mithril. Qui l’a emballée s’attendait à des ennuis, et en a eu."
	L["sub.21243.plaque"] = "Assez gros pour avaler une bourse entière, et il l’a fait."
	L["sub.6297.plaque"] = "Don de l’eau. Propriétaire inconnu, et de préférence qu’il le reste."
	L["sub.6301.plaque"] = "Appartenait à quelqu’un qui menait des chariots. On dirait qu’il en attend encore un."
	L["sub.6307.plaque"] = "L’encre a coulé il y a longtemps. Le bouchon, à son honneur, a tenu."
	L["sub.6351.plaque"] = "Tombée une fois, à première vue, puis une autre pour faire bonne mesure."
	L["sub.6352.plaque"] = "Emballée pour un voyage au sec. Elle ne l’a pas eu."
	L["sub.6353.plaque"] = "Assez petit pour être perdu par-dessus bord. Quelqu’un l’a prouvé."
	L["sub.6354.plaque"] = "Petit, verrouillé, et plus pénible à ouvrir qu’il ne l’a jamais été à porter."
	L["sub.6355.plaque"] = "Conçu pour survivre à tout. La mer met l’affirmation à l’épreuve."
	L["sub.6356.plaque"] = "Quelqu’un l’a verrouillé, quelqu’un l’a coulé, et ni l’un ni l’autre n’est revenu le chercher."
	L["sub.6357.plaque"] = "Scellée contre l’eau. L’eau a été patiente."
	L["sub.6455.plaque"] = "Où est passé le chariot fait toujours l’objet d’une enquête."
	L["sub.6456.plaque"] = "Prière de ne pas toucher la pièce exposée."
	L["sub.6457.plaque"] = "Un gnome appellerait ça « presque en état de marche »."
	L["sub.6643.plaque"] = "Un petit poisson au grand appétit, sans aucune idée de ce qui compte comme nourriture."
	L["sub.6645.plaque"] = "Il a mordu dans quelque chose de bien trop gros pour l’avaler, et l’a avalé quand même."
	L["sub.6647.plaque"] = "Nourri au fond, là où finit tout ce que les gens laissent tomber."
	L["sub.6717.plaque"] = "Les pièces de rechange d’un bricoleur, tombées par-dessus bord en plein travail. Il jure que le bateau fuyait avant."
	L["sub.6718.plaque"] = "Des pièces pour un leurre de canard mécanique, du genre qui explose. Tenues bien à l’écart des vrais canards."
	L["sub.7973.plaque"] = "Ne dit rien de ce qu’elle contient. Ouvrez-la quand même ; parfois, c’est une perle."
	L["sub.8366.plaque"] = "A mangé quelque chose de brillant. Peut-être même du mithril, cette fois."
	L["title.complete.junk.text"] = "Collectionneur de bottes"
	L["title.complete.ledger.text"] = "Pêcheur d’Azeroth"
	L["title.complete.treasure.text"] = "Gardien des cargaisons perdues"
	L["title.complete.trophy.text"] = "Fait-pencher-la-balance"
	L["title.complete.varieties.text"] = "Gardien de toutes les couleurs"
	L["title.level1.text"] = "Vairon"
	L["title.level10.text"] = "Barboteur"
	L["title.level20.text"] = "Lanceur de ligne"
	L["title.level30.text"] = "Pêcheur confirmé"
	L["title.level40.text"] = "Vieux loup de mer"
	L["title.level50.text"] = "Liseur de marées"
	L["title.level60.text"] = "Pair de Nat"
	L["title.prestige1.text"] = "Retour de marée"
	L["title.prestige10.text"] = "Laisse de haute mer"
	L["title.prestige5.text"] = "Contre-courant"
	L["title.zonemaster.text"] = "Gardien des eaux : {zone}"
end)
